<section class="vc-page-actions"><div><span class="vc-status info" id="vp-summary">Loading your coupons…</span></div><button type="button" class="vc-btn primary" id="vp-new"><i class="fa-solid fa-plus"></i> Create coupon</button></section>
<section class="vc-card"><div class="vc-card-head"><h2>Your coupons</h2><span class="vc-help">Only coupons belonging to this store appear here.</span></div><div class="vc-table-wrap"><table class="vc-table"><thead><tr><th>Code</th><th>Discount</th><th>Minimum order</th><th>Redemptions</th><th>Schedule</th><th>Status</th><th>Actions</th></tr></thead><tbody id="vp-rows"><tr><td colspan="7">Loading…</td></tr></tbody></table></div></section>
<dialog class="vc-dialog" id="vp-dialog"><div class="vc-dialog-head"><h2 id="vp-dialog-title">Create coupon</h2><button type="button" class="vc-btn small" id="vp-close">Close</button></div><form class="vc-dialog-body" id="vp-form"><input type="hidden" name="coupon_id"><div class="vc-form-grid"><div class="vc-field"><label>Coupon code</label><input class="vc-input" name="code" required pattern="[A-Za-z0-9_-]{4,40}" maxlength="40" autocomplete="off"></div><div class="vc-field"><label>Discount type</label><select class="vc-select" name="discount_type" required><option value="percent">Percentage</option><option value="fixed">Fixed amount (₹)</option></select></div><div class="vc-field"><label>Discount value</label><input class="vc-input" name="discount_value" type="number" step="0.01" min="0.01" required></div><div class="vc-field"><label>Minimum order (₹)</label><input class="vc-input" name="min_order_amount" type="number" step="0.01" min="0" value="0" required></div><div class="vc-field"><label>Maximum discount (₹, optional)</label><input class="vc-input" name="max_discount_amount" type="number" step="0.01" min="0"></div><div class="vc-field"><label>Total usage limit (optional)</label><input class="vc-input" name="usage_limit" type="number" min="1" max="1000000"></div><div class="vc-field"><label>Per-customer limit</label><input class="vc-input" name="per_customer_limit" type="number" min="1" max="100" value="1" required></div><div class="vc-field"><label>Status</label><select class="vc-select" name="status"><option value="draft">Draft</option><option value="active">Active</option><option value="paused">Paused</option></select></div><div class="vc-field"><label>Starts</label><input class="vc-input" name="starts_at" type="datetime-local" required></div><div class="vc-field"><label>Ends</label><input class="vc-input" name="ends_at" type="datetime-local" required></div></div><p class="vc-help">A coupon can only be used during its schedule and while active. Delivery benefits are configured in Delivery, not as a coupon type.</p><div class="vc-form-actions"><button class="vc-btn primary" type="submit">Save coupon</button></div></form></dialog>
